-- Common Philippine credentials for faculty profiles, reviewed 2026-10-01.
-- This is a selection catalog, not a determination of credential validity.
CREATE TABLE IF NOT EXISTS tbl_faculty_eligibilities (
  eligibility_id INT UNSIGNED NOT NULL AUTO_INCREMENT,
  code VARCHAR(80) NOT NULL,
  name VARCHAR(200) NOT NULL,
  category VARCHAR(80) NOT NULL,
  issuing_body VARCHAR(80) NOT NULL,
  search_terms VARCHAR(500) NOT NULL DEFAULT '',
  source_url VARCHAR(500) NOT NULL,
  sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (eligibility_id),
  UNIQUE KEY uniq_faculty_eligibility_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS tbl_faculty_profile_eligibilities (
  user_id INT NOT NULL,
  eligibility_id INT UNSIGNED NOT NULL,
  PRIMARY KEY (user_id, eligibility_id),
  KEY idx_profile_eligibility (eligibility_id),
  CONSTRAINT fk_profile_eligibility_profile FOREIGN KEY (user_id)
    REFERENCES tbl_faculty_profiles (user_id) ON DELETE CASCADE,
  CONSTRAINT fk_profile_eligibility_catalog FOREIGN KEY (eligibility_id)
    REFERENCES tbl_faculty_eligibilities (eligibility_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

ON DUPLICATE KEY UPDATE name = VALUES(name), category = VALUES(category),
  issuing_body = VALUES(issuing_body), search_terms = VALUES(search_terms),
  source_url = VALUES(source_url), sort_order = VALUES(sort_order);

